function rebuildAvatar(o,message){disposeRuntime(o.id);buildRuntime(o);markChanged();updateUi();if(message)showToast(message)}
function renderAvatarCustomizer(o){
 o.avatarSettings.look={...defaultAvatarLook(),...(o.avatarSettings.look||{})};
 $('#avatar-category-tabs').innerHTML=Object.entries(avatarCatalog).map(([key,category])=>`<button type="button" role="tab" aria-selected="${key===activeAvatarCategory}" class="${key===activeAvatarCategory?'active':''}" data-avatar-category="${key}"><i>${category.icon}</i><span>${category.label}</span><em>${escapeHtml(category.items.find(item=>item[0]===o.avatarSettings.look[key])?.[1]||'None')}</em></button>`).join('');
 const category=avatarCatalog[activeAvatarCategory];$('#avatar-category-title').textContent=category.label;$('#avatar-variants').setAttribute('aria-label',`${category.label} choices`);$('#avatar-variants').innerHTML=category.items.map(([key,label],index)=>`<button type="button" role="radio" aria-checked="${o.avatarSettings.look[activeAvatarCategory]===key}" class="${o.avatarSettings.look[activeAvatarCategory]===key?'active':''}" data-avatar-variant="${key}"><i style="--variant:${index}">${category.icon}</i><span>${label}</span></button>`).join('');
 $('#avatar-piece-count').textContent=`${Object.values(o.avatarSettings.look).filter(value=>value!=='none').length} fitted pieces`;
}
