let activeStarterCategory='all',selectedStarterId='';
function starterStroke([tool,x1,y1,x2,y2,width]){return{tool,width,points:[{x:x1,y:y1},{x:x2,y:y2}]}}
function starterThumbnail(model){return `<svg viewBox="0 0 480 280" aria-hidden="true"><g fill="none" stroke="${model.color}" stroke-linecap="round" stroke-linejoin="round">${model.strokes.map(stroke=>strokeMarkup(starterStroke(stroke))).join('')}</g></svg>`}
function renderCustomStarters(){
 $('#starter-category-tabs').innerHTML=Object.entries(customStarterCategories).map(([key,label])=>`<button type="button" class="${key===activeStarterCategory?'active':''}" data-starter-category="${key}" aria-pressed="${key===activeStarterCategory}">${label}</button>`).join('');
 const visible=customStarterModels.filter(model=>activeStarterCategory==='all'||model.type===activeStarterCategory);
 $('#starter-model-grid').innerHTML=visible.map(model=>`<button type="button" role="listitem" class="starter-model-card ${model.id===selectedStarterId?'active':''}" data-starter-model="${model.id}" style="--starter-color:${model.color}" aria-pressed="${model.id===selectedStarterId}"><span>${starterThumbnail(model)}<i>${model.icon}</i></span><b>${model.name}</b><small>${customStarterCategories[model.type]} · ${model.behavior}</small></button>`).join('');
}
function loadCustomStarter(model){
 selectedStarterId=model.id;drawingStrokes=model.strokes.map(starterStroke);$('#custom-item-name').value=model.name;$('#custom-item-type').value=model.type;$('#custom-item-color').value=model.color;$('#custom-item-behavior').value=model.behavior;$('#custom-item-animation').value=model.animation;$('#custom-item-action').value=model.action;$('#custom-model-depth').value=model.depth;$('#custom-model-bevel').value=model.bevel;$('#custom-model-material').value=model.material;$('#starter-selection-status').textContent=`${model.name} loaded. Edit the silhouette or settings, then save all three 3D forms.`;renderCustomStarters();updateDrawing();drawingSvg.scrollIntoView({behavior:'smooth',block:'center'});
}
$('#starter-category-tabs').addEventListener('click',event=>{const button=event.target.closest('[data-starter-category]');if(!button)return;activeStarterCategory=button.dataset.starterCategory;renderCustomStarters()});
$('#starter-model-grid').addEventListener('click',event=>{const button=event.target.closest('[data-starter-model]');if(button)loadCustomStarter(customStarterModels.find(model=>model.id===button.dataset.starterModel))});
$('#start-blank-item').addEventListener('click',()=>{selectedStarterId='';drawingStrokes=[];$('#custom-item-name').value='My custom item';$('#starter-selection-status').textContent='Blank canvas ready. Draw a silhouette below.';renderCustomStarters();updateDrawing();drawingSvg.scrollIntoView({behavior:'smooth',block:'center'})});
const selectedClipOns=()=>[...document.querySelectorAll('[data-clip-on][aria-pressed="true"]')].map(button=>button.dataset.clipOn);
const svgPoint=event=>{const rect=drawingSvg.getBoundingClientRect();return{x:Math.round((event.clientX-rect.left)/rect.width*480),y:Math.round((event.clientY-rect.top)/rect.height*280)}};
const pathFor=stroke=>{const points=stroke.points||[];if(!points.length)return'';const a=points[0],b=points.at(-1);if(stroke.tool==='rectangle')return`M${a.x} ${a.y}H${b.x}V${b.y}H${a.x}Z`;if(stroke.tool==='circle'){const rx=Math.abs(b.x-a.x),ry=Math.abs(b.y-a.y);return`M${a.x-rx} ${a.y}a${rx} ${ry} 0 1 0 ${rx*2} 0a${rx} ${ry} 0 1 0 ${-rx*2} 0`;}return points.map((p,i)=>`${i?'L':'M'}${p.x} ${p.y}`).join(' ')};
const strokeMarkup=stroke=>`<path d="${pathFor(stroke)}" stroke-width="${stroke.width}" vector-effect="non-scaling-stroke"/>`;
function svgDocument(){const name=escapeHtml($('#custom-item-name').value||'Custom game item'),clips=selectedClipOns().join(','),behavior=$('#custom-item-behavior').value;return`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 480 280" data-game-behavior="${behavior}" data-clip-ons="${clips}"><title>${name}</title><desc>Portable MUZIKAZ game item silhouette with embedded behavior and fitted add-on metadata.</desc><metadata>{"behavior":"${behavior}","clipOns":"${clips}"}</metadata><g fill="none" stroke="${$('#custom-item-color').value}" stroke-linecap="round" stroke-linejoin="round">${drawingStrokes.map(strokeMarkup).join('')}</g></svg>`}
function updateDrawing(){strokeLayer.innerHTML=drawingStrokes.map(strokeMarkup).join('');previewStrokes.innerHTML=strokeLayer.innerHTML;activeStroke.setAttribute('d',draftStroke?pathFor(draftStroke):'');activeStroke.setAttribute('stroke-width',draftStroke?.width||18);$('#drawing-status').textContent=drawingStrokes.length?`${drawingStrokes.length} shape${drawingStrokes.length===1?'':'s'} connected · ready to extrude`:'Draw directly on the grid. Your paths become real 3D geometry.';updateMakerPreview()}
function updateMakerPreview(){$('#maker-preview-name').textContent=$('#custom-item-name').value||'Untitled item';$('#maker-preview').style.setProperty('--item-color',$('#custom-item-color').value);$('#brush-size-output').textContent=`${$('#custom-brush-size').value} px`;$('#model-depth-output').textContent=`${Number($('#custom-model-depth').value).toFixed(2)} m`;$('#model-bevel-output').textContent=`${Number($('#custom-model-bevel').value).toFixed(2)} m`}
$('#custom-form-toggle').addEventListener('click',event=>{const button=event.target.closest('[data-custom-form]');if(!button)return;activeCustomForm=button.dataset.customForm;document.querySelectorAll('[data-custom-form]').forEach(item=>{const active=item===button;item.classList.toggle('active',active);item.setAttribute('aria-pressed',active)});$('#maker-preview').dataset.form=activeCustomForm;$('#maker-preview').querySelector('small').textContent=`${customFormPresets[activeCustomForm].label.toUpperCase()} 3D PREVIEW`});
$('#custom-clip-ons').addEventListener('click',event=>{const button=event.target.closest('[data-clip-on]');if(!button)return;const active=button.getAttribute('aria-pressed')!=='true';button.setAttribute('aria-pressed',active);button.classList.toggle('active',active);const count=selectedClipOns().length;$('#clip-on-count').textContent=`${count} fitted`});
document.querySelectorAll('[data-draw-tool]').forEach(button=>button.addEventListener('click',()=>{drawingTool=button.dataset.drawTool;document.querySelectorAll('[data-draw-tool]').forEach(item=>{item.classList.toggle('active',item===button);item.setAttribute('aria-pressed',item===button)})}));
drawingSvg.addEventListener('pointerdown',event=>{event.preventDefault();drawingSvg.setPointerCapture(event.pointerId);draftStroke={tool:drawingTool,width:Number($('#custom-brush-size').value),points:[svgPoint(event)]}});drawingSvg.addEventListener('pointermove',event=>{if(!draftStroke)return;const point=svgPoint(event);if(draftStroke.tool==='pencil')draftStroke.points.push(point);else draftStroke.points[1]=point;updateDrawing()});drawingSvg.addEventListener('pointerup',event=>{if(!draftStroke)return;if(draftStroke.points.length>1)drawingStrokes.push(draftStroke);draftStroke=null;updateDrawing()});
$('#undo-model-stroke').addEventListener('click',()=>{drawingStrokes.pop();updateDrawing()});$('#clear-model-drawing').addEventListener('click',()=>{drawingStrokes=[];updateDrawing()});
$('#download-model-svg').addEventListener('click',()=>{if(!drawingStrokes.length)return $('#drawing-status').textContent='Draw at least one shape before downloading.';const blob=new Blob([svgDocument()],{type:'image/svg+xml'}),link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`${($('#custom-item-name').value||'custom-model').trim().replace(/[^a-z0-9]+/gi,'-').toLowerCase()}.svg`;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),0)});
['custom-item-name','custom-item-color','custom-brush-size','custom-model-depth','custom-model-bevel'].forEach(id=>$(`#${id}`).addEventListener('input',updateMakerPreview));
$('#open-item-maker').addEventListener('click',()=>{renderCustomStarters();updateDrawing();$('#item-maker').showModal()});
$('#item-maker-form').addEventListener('submit',e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();const name=$('#custom-item-name').value.trim();if(!name||!drawingStrokes.length){$('#drawing-status').textContent='Draw at least one model shape to continue.';return}const svg=svgDocument(),groupId=`custom-set-${uid()}`,base={name,type:$('#custom-item-type').value,size:72,image:`data:image/svg+xml,${encodeURIComponent(svg)}`,color:$('#custom-item-color').value,behavior:$('#custom-item-behavior').value,animation:$('#custom-item-animation').value,action:$('#custom-item-action').value,strokes:cloneData(drawingStrokes),clipOns:selectedClipOns(),drawingSettings:{depth:Number($('#custom-model-depth').value),bevel:Number($('#custom-model-bevel').value),material:$('#custom-model-material').value},groupId,custom:true,assetKind:'custom-svg'},created=Object.entries(customFormPresets).map(([form,preset])=>({...base,id:`custom-${form}-${uid()}`,form,formLabel:preset.label}));customModels.push(...created);localStorage.setItem(CUSTOM_KEY,JSON.stringify(customModels));renderLibrary();$('#item-maker').close();drawingStrokes=[];document.querySelectorAll('[data-clip-on]').forEach(button=>{button.setAttribute('aria-pressed','false');button.classList.remove('active')});$('#clip-on-count').textContent='0 fitted';updateDrawing();showToast(`${name} saved in 3 switchable 3D forms`);beginPlacement(created.find(model=>model.form===activeCustomForm)?.id||created[0].id)});

const sideCanvas=$('#side-view-canvas'),side=sideCanvas.getContext('2d');function drawSideView(){const rect=sideCanvas.getBoundingClientRect(),dpr=Math.min(devicePixelRatio,2),w=Math.max(1,Math.round(rect.width*dpr)),h=Math.max(1,Math.round(rect.height*dpr));if(sideCanvas.width!==w||sideCanvas.height!==h){sideCanvas.width=w;sideCanvas.height=h}side.setTransform(dpr,0,0,dpr,0,0);const W=rect.width,H=rect.height;side.clearRect(0,0,W,H);side.fillStyle='#07100b';side.fillRect(0,0,W,H);side.beginPath();for(let px=0;px<=W;px++){const x=px/W*40-20,y=H-28-terrainHeight(x,0)*20;px?side.lineTo(px,y):side.moveTo(px,y)}side.lineTo(W,H);side.lineTo(0,H);side.fillStyle='#264c2d';side.fill();side.strokeStyle='#80ba5a';side.stroke();sceneData.objects.forEach(o=>{const x=(o.position.x+20)/40*W,ground=H-28-groundAt(o.position.x,o.position.z)*20,top=ground-o.groundOffset*20-18*o.scale.y;side.strokeStyle=o.groundOffset?'#ffcc3d':'#63eaff';side.lineWidth=3;side.beginPath();side.moveTo(x,ground);side.lineTo(x,top);side.stroke();side.fillStyle=o.id===selectedId?'#fff':o.materialSettings.accent;side.fillRect(x-4,top-4,8,8)})}
window.MuzikazEnvironmentBuilder={getScene:()=>cloneData(sceneData),getObject3D:id=>runtime.get(id)?.root||null,snapToGround:id=>{const o=sceneData.objects.find(item=>item.id===id);if(o){o.groundOffset=0;updateTransform(o)}}};
function resize(){const rect=renderer.domElement.parentElement.getBoundingClientRect(),w=rect.width,h=rect.height;if(renderer.domElement.width!==Math.round(w*renderer.getPixelRatio())||renderer.domElement.height!==Math.round(h*renderer.getPixelRatio())){renderer.setSize(w,h,false);camera.aspect=w/h;camera.updateProjectionMatrix()}}
function animate(){requestAnimationFrame(animate);resize();const dt=Math.min(clock.getDelta(),.05),elapsed=clock.elapsedTime;controls.update();weatherLayer.children.forEach(layer=>{if(layer.userData.rain){const p=layer.geometry.attributes.position;for(let i=0;i<p.count;i++)p.setY(i,p.getY(i)-dt*(sceneData.weather==='storm'?13:8));for(let i=0;i<p.count;i++)if(p.getY(i)<.2)p.setY(i,14);p.needsUpdate=true}});runtime.forEach((rt,id)=>{const o=sceneData.objects.find(x=>x.id===id);if(rt.mixer&&o?.animationState.enabled)rt.mixer.update(dt);if(!rt.mixer&&o?.animationState.enabled){const speed=o.animationState.speed||1,clip=o.animationState.clip;if(clip==='float'||clip==='bounce')rt.root.position.y=o.position.y+Math.abs(Math.sin(elapsed*speed*(clip==='bounce'?4:2)))*(clip==='bounce'?.24:.18);if(clip==='dance')rt.root.rotation.z=Math.sin(elapsed*speed*6)*.12;if(clip==='walk'||clip==='crawl')rt.root.rotation.y=o.rotation.y+Math.sin(elapsed*speed*(clip==='crawl'?7:3))*(clip==='crawl'?.16:.08);if(clip==='spin')rt.root.rotation.y=o.rotation.y+elapsed*speed*.7}rt.root.traverse(n=>{if(n.userData.effect){n.scale.y=1+Math.sin(elapsed*7)*.12;n.rotation.y=elapsed*.8}})});updateBuilderModels(placedGroup,elapsed);renderer.render(world,camera);drawSideView()}animate();

const requested=new URLSearchParams(location.search).get('layout'),saved=readJson(STORAGE_KEY,readJson(LEGACY_KEY,null));if(saved&&Array.isArray(saved.objects))sceneData={...sceneData,...saved,layout:layouts[saved.layout]?saved.layout:'grand-floor',objects:saved.objects.filter(o=>modelFor(o.modelId)).map(migrateObject)};if(requested&&layouts[requested])sceneData.layout=requested;const tray=readJson(TRAY_KEY,[]);if(!sceneData.objects.length)tray.filter(i=>modelFor(i.id)).forEach((i,n)=>sceneData.objects.push(makeObject(i.id,-8+(n%5)*4,-5+Math.floor(n/5)*4)));$('#scene-name').value=sceneData.name;$('#layout-select').value=sceneData.layout;$('#weather-select').value=sceneData.weather||'clear';$('#layout-label').textContent=layouts[sceneData.layout].name.toUpperCase();$('#layout-description').textContent=layouts[sceneData.layout].description;$('#land-canvas').className=`land-canvas layout-${sceneData.layout}`;shapeTerrain();renderAtlas();renderLibrary();rebuildAll();populateCompleteCatalog().then(()=>{const wanted=requested||saved?.layout;if(wanted&&layouts[wanted]&&sceneData.layout!==wanted)updateLayout(wanted)});

// Avatar Look Lab popup: component-only SVG preview, per-piece fitting, and reversible edits.
const avatarDialog=$('#avatar-customizer');
let avatarPreviewView='front',avatarUndo=[],avatarRedo=[];
const defaultPieceTransform=()=>({color:selected()?.avatarSettings?.outfitColor||'#63eaff',scale:1,rotation:0,x:0,y:0});
function ensureAvatarState(o){o.avatarSettings.transforms={...(o.avatarSettings.transforms||{})};for(const key of Object.keys(avatarCatalog))o.avatarSettings.transforms[key]={...defaultPieceTransform(),...(o.avatarSettings.transforms[key]||{})}}
function avatarSnapshot(o){ensureAvatarState(o);return cloneData({look:o.avatarSettings.look,bodyColor:o.avatarSettings.bodyColor,outfitColor:o.avatarSettings.outfitColor,transforms:o.avatarSettings.transforms,customized:o.avatarSettings.customized})}
function applyAvatarSnapshot(o,state){Object.assign(o.avatarSettings,cloneData(state));rebuildAvatar(o)}
function pushAvatarHistory(o){avatarUndo.push(avatarSnapshot(o));if(avatarUndo.length>40)avatarUndo.shift();avatarRedo=[]}
function pieceTransform(o,key){ensureAvatarState(o);return o.avatarSettings.transforms[key]}
function previewPiece(key,value,color){if(value==='none')return'';const shapes={face:`<g><circle cx="137" cy="104" r="5"/><circle cx="163" cy="104" r="5"/><path d="M140 121 Q150 128 160 121"/></g>`,hat:`<path d="M112 81 Q150 43 188 81 L181 91 H119Z"/>`,glasses:`<g><rect x="119" y="96" width="25" height="18" rx="7"/><rect x="156" y="96" width="25" height="18" rx="7"/><path d="M144 103h12"/></g>`,headphones:`<path d="M110 112V98a40 40 0 0180 0v14M109 108h12v30h-12zm70 0h12v30h-12z"/>`,necklace:`<path d="M126 150 Q150 180 174 150 M145 174l5 8 5-8"/>`,rings:`<g><circle cx="99" cy="224" r="5"/><circle cx="201" cy="224" r="5"/></g>`,top:`<path d="M112 163 L82 190 101 210 112 198v70h76v-70l11 12 19-20-30-27z"/>`,bottom:`<path d="M113 263h74l9 94h-37l-9-65-9 65h-37z"/>`,accessory:value==='wings'?`<path d="M112 182 Q48 145 62 245l52-31m74-32q64-37 50 63l-52-31"/>`:`<path d="M188 174h29v73h-29z"/>`};return `<g class="avatar-piece" data-preview-piece="${key}" fill="${color}" stroke="${color}" stroke-width="6" stroke-linecap="round" stroke-linejoin="round">${shapes[key]||''}</g>`}
function avatarSvg(o){ensureAvatarState(o);const side=avatarPreviewView==='side',back=avatarPreviewView==='back',parts=Object.entries(o.avatarSettings.look).map(([key,value])=>previewPiece(key,value,pieceTransform(o,key).color)).join('');return `<svg viewBox="0 0 300 400" role="img" aria-label="${avatarPreviewView} view of customized avatar"><ellipse cx="150" cy="378" rx="65" ry="12" fill="#000" opacity=".5"/><g ${side?'transform="translate(32 0) scale(.78 1)"':back?'transform="translate(300 0) scale(-1 1)"':''}><circle cx="150" cy="108" r="48" fill="${o.avatarSettings.bodyColor}"/><path d="M116 151 Q150 139 184 151l25 112-18 112h-34l-7-88-7 88h-34l-18-112z" fill="#18251c" stroke="#526459" stroke-width="5"/><path d="M116 168L78 245M184 168l38 77" stroke="${o.avatarSettings.bodyColor}" stroke-width="22" stroke-linecap="round"/>${parts}</g></svg>`}
function renderAvatarModal(){const o=selected();if(!o)return;ensureAvatarState(o);const category=avatarCatalog[activeAvatarCategory],t=pieceTransform(o,activeAvatarCategory);$('#avatar-modal-categories').innerHTML=Object.entries(avatarCatalog).map(([key,c])=>`<button type="button" data-modal-avatar-category="${key}" class="${key===activeAvatarCategory?'active':''}"><i>${c.icon}</i><span>${c.label}</span><small>${escapeHtml(c.items.find(x=>x[0]===o.avatarSettings.look[key])?.[1]||'None')}</small></button>`).join('');$('#avatar-modal-category-title').textContent=category.label;$('#avatar-modal-options').innerHTML=category.items.map(([key,label])=>`<button type="button" role="radio" aria-checked="${o.avatarSettings.look[activeAvatarCategory]===key}" class="${o.avatarSettings.look[activeAvatarCategory]===key?'active':''}" data-modal-avatar-option="${key}"><i>${category.icon}</i><span>${escapeHtml(label)}</span></button>`).join('');$('#avatar-live-preview').innerHTML=avatarSvg(o);$('#avatar-preview-status').textContent=`${avatarPreviewView[0].toUpperCase()+avatarPreviewView.slice(1)} view · ${category.label} fitted`;for(const [id,value,suffix] of [['avatar-piece-scale',Math.round(t.scale*100),'%'],['avatar-piece-rotation',t.rotation,'°'],['avatar-piece-x',t.x,''],['avatar-piece-y',t.y,'']]){$(`#${id}`).value=value;$(`#${id}-output`).textContent=`${value}${suffix}`}$('#avatar-piece-color').value=t.color;document.querySelectorAll('[data-preview-piece]').forEach(piece=>{const pt=pieceTransform(o,piece.dataset.previewPiece);piece.style.transform=`translate(${pt.x}px,${-pt.y}px) rotate(${pt.rotation}deg) scale(${pt.scale})`});$('#avatar-undo').disabled=!avatarUndo.length;$('#avatar-redo').disabled=!avatarRedo.length;$('#avatar-remove-piece').disabled=o.avatarSettings.look[activeAvatarCategory]==='none'}
function setAvatarPieceValue(mutator,message){const o=selected();if(!o)return;pushAvatarHistory(o);mutator(o);o.avatarSettings.customized=Object.entries(o.avatarSettings.look).some(([k,v])=>k==='face'?v!=='classic':v!=='none');rebuildAvatar(o,message);renderAvatarModal()}
$('#open-avatar-customizer').addEventListener('click',()=>{if(!selected())return;avatarUndo=[];avatarRedo=[];renderAvatarModal();avatarDialog.showModal()});
$('#close-avatar-customizer').addEventListener('click',()=>avatarDialog.close());
$('#avatar-save-close').addEventListener('click',()=>{const o=selected();if(o){localStorage.setItem('muzikaz.avatarLook.v2',JSON.stringify(avatarSnapshot(o)));persist(`${o.avatarSettings.displayName}'s exact avatar look saved`)}avatarDialog.close()});
$('#avatar-modal-categories').addEventListener('click',e=>{const b=e.target.closest('[data-modal-avatar-category]');if(b){activeAvatarCategory=b.dataset.modalAvatarCategory;renderAvatarModal()}});
$('#avatar-modal-options').addEventListener('click',e=>{const b=e.target.closest('[data-modal-avatar-option]');if(b)setAvatarPieceValue(o=>o.avatarSettings.look[activeAvatarCategory]=b.dataset.modalAvatarOption,`${avatarCatalog[activeAvatarCategory].label} updated`)});
$('#avatar-view-tabs').addEventListener('click',e=>{const b=e.target.closest('[data-avatar-view]');if(!b)return;avatarPreviewView=b.dataset.avatarView;document.querySelectorAll('[data-avatar-view]').forEach(x=>x.classList.toggle('active',x===b));renderAvatarModal()});
$('#avatar-remove-piece').addEventListener('click',()=>setAvatarPieceValue(o=>o.avatarSettings.look[activeAvatarCategory]=activeAvatarCategory==='face'?'classic':'none','Component removed'));
$('#avatar-reset-category').addEventListener('click',()=>setAvatarPieceValue(o=>{o.avatarSettings.look[activeAvatarCategory]=defaultAvatarLook()[activeAvatarCategory];o.avatarSettings.transforms[activeAvatarCategory]=defaultPieceTransform()},'Category reset'));
$('#avatar-reset-all').addEventListener('click',()=>setAvatarPieceValue(o=>{o.avatarSettings.look=defaultAvatarLook();o.avatarSettings.transforms={};ensureAvatarState(o)},'Avatar reset'));
for(const [id,key,convert] of [['avatar-piece-color','color',String],['avatar-piece-scale','scale',v=>Number(v)/100],['avatar-piece-rotation','rotation',Number],['avatar-piece-x','x',Number],['avatar-piece-y','y',Number]]){const control=$(`#${id}`);let captured=false;const capture=()=>{const o=selected();if(o&&!captured){pushAvatarHistory(o);captured=true}};control.addEventListener('pointerdown',capture);control.addEventListener('focus',capture);control.addEventListener('input',()=>{const o=selected();if(!o)return;capture();pieceTransform(o,activeAvatarCategory)[key]=convert(control.value);o.avatarSettings.customized=true;renderAvatarModal()});control.addEventListener('change',()=>{const o=selected();if(!o)return;captured=false;rebuildAvatar(o,`${avatarCatalog[activeAvatarCategory].label} fit updated`);renderAvatarModal()})}
$('#avatar-undo').addEventListener('click',()=>{const o=selected();if(!o||!avatarUndo.length)return;avatarRedo.push(avatarSnapshot(o));applyAvatarSnapshot(o,avatarUndo.pop());renderAvatarModal()});
$('#avatar-redo').addEventListener('click',()=>{const o=selected();if(!o||!avatarRedo.length)return;avatarUndo.push(avatarSnapshot(o));applyAvatarSnapshot(o,avatarRedo.pop());renderAvatarModal()});
